"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[5545],{7300(e){e.exports=JSON.parse('{"title":"\ub9ac\uc561\ud2b8 \ucef4\ud3ec\ub10c\ud2b8\uc758 \ub274\ub178\ub9d0","date":"2026-02-18","coverUrl":"/kudzu-based-bench/assets/notion/2252a860e79eaccc.png","html":"<h1 data-notion-block-id=\\"304e548d-8a8e-806e-b339-d908a8270133\\">Beyond the Article: \ud55c \uac78\uc74c \ub354</h1><h2 data-notion-block-id=\\"304e548d-8a8e-80f5-9472-fd42e57d946c\\" id=\\"304e548d-8a8e-80f5-9472-fd42e57d946c\\">\ub9ac\uc561\ud2b8 \ucef4\ud3ec\ub10c\ud2b8\uc758 \ub274\ub178\ub9d0</h2><a href=\\"https://shud.in/thoughts/build-bulletproof-react-components\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://shud.in/thoughts/build-bulletproof-react-components</a><p data-notion-block-id=\\"307e548d-8a8e-80c1-b2cc-e4310ad618d2\\">\ub9ac\uc561\ud2b8 \uac1c\ubc1c\uc758 \uc911\uc2ec\uc774\ub77c\uace0 \ubcfc \uc218 \uc788\ub294 \ucef4\ud3ec\ub10c\ud2b8\uc640 \ud6c5\uc740 \ub9ac\uc561\ud2b8 \uc0dd\ud0dc\uacc4\uc758 \uc778\uae30 \uc911\uc2ec\uc774 \ub418\uc5c8\uc2b5\ub2c8\ub2e4. \ud558\uc9c0\ub9cc \ub9ac\uc561\ud2b8 \ud6c5\uacfc API\uc758 \uc81c\ud55c\uc131, \ub2e4\uc591\ud654, \uc2e4\ud589\ud658\uacbd\uc758 \ub2e4\uc591\ud654\u2026 \uc5ec\ub7ec\uac00\uc9c0\ub97c \uace0\ub824\ud574\uc57c \ud558\ub294 \uc0c1\ud669\uc774 \ub418\uc5c8\uc2b5\ub2c8\ub2e4. \uc774 \uae00\uc774 \ubaa8\ub4e0 \uc5e3\uc9c0\ucf00\uc774\uc2a4\uc5d0 \ud574\uacb0\ucc45\uc744 \uc81c\uc2dc\ud574\uc8fc\uc9c4 \uc54a\uc2b5\ub2c8\ub2e4. \ud558\uc9c0\ub9cc <a href=\\"https://ones-to-watch.ethansup.net/news/post/1cfe548d-8a8e-8030-818c-eea9d093d4aa#1d4e548d-8a8e-8049-8d15-e702077d34a3\\">useState\uac00 \uc544\ub2c8\ub77c \uc0c1\ud0dc\uc640 \uce5c\ud574\uc9c0\uae30</a>\uc640 \uac19\uc774, React API\uc758 \uc0ac\uc6a9 \ubc29\ud5a5\uc774\ub098 \uc2e4\ud589\ud658\uacbd\uc5d0 \ub9de\uac8c \ucf54\ub4dc\ub97c \ub9de\uac8c \uad6c\uc131\ud574\uc57c \ud55c\ub2e4\ub294 \uac83\uc744 \uc5ec\ub7ec \ubc29\uba74\uc5d0\uc11c \uc18c\uac1c\ud574\uc90d\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"304e548d-8a8e-80de-8a9a-c6c8306668c9\\" id=\\"304e548d-8a8e-80de-8a9a-c6c8306668c9\\">\uc0c8\ub85c\uc6b4 Rolldown, \uc5b4\ub5bb\uac8c \ub3d9\uc791\ud558\ub294\uac00</h2><a href=\\"https://www.atriiy.dev/blog/rolldown-high-performance-code-splitting\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.atriiy.dev/blog/rolldown-high-performance-code-splitting</a><p data-notion-block-id=\\"305e548d-8a8e-802f-8bf0-fbf616bf0a03\\">Rolldown\uc740 Rollup\uc744 \ub300\uccb4\ud558\uae30 \uc704\ud55c \ubc88\ub4e4\ub7ec\uc785\ub2c8\ub2e4. \ub2e4\ub978 \ubc88\ub4e4\ub7ec\uac00 \uc5b4\ub5bb\uac8c \ub3d9\uc791\ud558\ub294\uc9c0\ub294 <a href=\\"https://ones-to-watch.ethansup.net/news/post/2a7e548d-8a8e-8035-8091-f96685017e48#2aee548d-8a8e-8043-83ec-fffe6be54735\\">\ubc88\ub4e4\ub7ec\ub9c8\ub2e4 Tree shaking\uc740 \uc5b4\ub5bb\uac8c \ub2e4\ub97c\uae4c</a>\uc5d0\uc11c \ubcf4\uc5ec\uc8fc\uc9c0\ub9cc, Rolldown\uc740 \ube44\uad50\uc801 \ucd5c\uc2e0 \ub77c\uc774\ube0c\ub7ec\ub9ac\uc774\uae30 \ub54c\ubb38\uc5d0 \uc815\ubcf4\uac00 \ubd80\uc871\ud569\ub2c8\ub2e4. \uc774 \uc2dc\ub9ac\uc988\uc5d0\uc11c \ubaa8\ub4c8 \uc2a4\uce94 \ub2e8\uacc4, \uc758\uc874\uc131 \ud2b8\ub9ac \uc0dd\uc131, \uadf8\ub9ac\uace0 Code spliting(\uacfc Tree shaking)\uc744 \uc18c\uac1c\ud569\ub2c8\ub2e4. \uc774 \uae00\uc5d0\uc11c Rolldown\uc774 \ubb34\uc5c7\uc778\uc9c0, \uc5b4\ub5bb\uac8c \ub3d9\uc791\ud558\ub294\uc9c0 \uc18c\uac1c\ud569\ub2c8\ub2e4. \uc2e4\uc81c Rust \ucf54\ub4dc\uc640 \uc2ec\ud654 \uc790\ub8cc\uad6c\uc870\ub97c \uae30\ubc18\uc73c\ub85c \uc18c\uac1c\ud558\ubbc0\ub85c \uc5b4\ub835\uc9c0\ub9cc, \uc5ec\ub7ec\uac00\uc9c0 \uc7a5\uc810\uacfc \ub3d9\uc791\ubc29\uc2dd\uc744 \uc790\uc138\ud788 \uc124\uba85\ud558\uace0 \uc788\uc73c\ubbc0\ub85c, \ud55c \ubc88 \ubcf4\uc2dc\uae38 \ucd94\ucc9c\ub4dc\ub9bd\ub2c8\ub2e4!</p><h2 data-notion-block-id=\\"305e548d-8a8e-80df-987b-f71fea6f9efe\\" id=\\"305e548d-8a8e-80df-987b-f71fea6f9efe\\">React\uc758 \uc885\ub8cc \uc560\ub2c8\uba54\uc774\uc158 \ubb38\uc81c</h2><a href=\\"https://barvian.me/react-exit-animations\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://barvian.me/react-exit-animations</a><p data-notion-block-id=\\"307e548d-8a8e-80d6-ab9c-d03ab7bd0d9a\\">React\uc5d0\uc11c\ub294 \uae30\ubcf8\uc801\uc73c\ub85c transition class(ex. <a href=\\"https://vuejs.org/guide/built-ins/transition\\">Vue\uc758 </a><a href=\\"https://vuejs.org/guide/built-ins/transition\\"><code>&#x3C;Transition></code></a>, <a href=\\"https://svelte.dev/docs/svelte/transition\\">Svelte\uc758 </a><a href=\\"https://svelte.dev/docs/svelte/transition\\"><code>transition:</code></a>)\ub97c \uc81c\uacf5\ud558\uc9c0 \uc54a\uc558\uc2b5\ub2c8\ub2e4. \uadf8\ub798\uc11c <a href=\\"https://reactcommunity.org/react-transition-group/\\">react-transition-group</a>\ub77c\uc774\ube0c\ub7ec\ub9ac\ub97c \uc0ac\uc6a9\ud588\uc5b4\uc57c \ud588\ub294\ub370, \uc774 \ube14\ub85c\uadf8\uc5d0\uc11c\ub294 React\uc758 <code>&#x3C;Suspense></code>\uc640 \ud6c5\uc744 \uc774\uc6a9\ud574\uc11c \uc27d\uac8c \uad6c\ud604\ud558\ub294 \ubc29\uc2dd\uc744 \uc18c\uac1c\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"307e548d-8a8e-80c0-80f1-c1d85ccc622b\\" id=\\"307e548d-8a8e-80c0-80f1-c1d85ccc622b\\">AI\uac00 \ub9cc\ub4dc\ub294 \ubbf8\ub798, \uc26c\uc6b4 \ud30c\ud2b8\ub294 \ub354 \uc26c\uc6cc\uc9c0\uace0, \uc5b4\ub824\uc6b4 \ud30c\ud2b8\ub294 \ub354 \uc5b4\ub824\uc6cc\uc9c8 \uac83.</h2><a href=\\"https://www.blundergoat.com/articles/ai-makes-the-easy-part-easier-and-the-hard-part-harder\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.blundergoat.com/articles/ai-makes-the-easy-part-easier-and-the-hard-part-harder</a><p data-notion-block-id=\\"307e548d-8a8e-80a4-91f7-c4fdb69f1409\\">\uc774\uc804\uc5d0 \uc18c\uac1c\ud588\ub358 AI\uc758 70%\ubb38\uc81c\uac19\uc774, \ubc14\uc774\ube0c\ucf54\ub529\uc774\ub77c\ub294 \ud574\uacb0\ucc45\uc774 \uae30\ubcf8\uc774 \ub41c\uac83\ucc98\ub7fc, \ub9ce\uc740 \uc81c\ud488\uc774 \ub098\uc624\uc9c0\ub9cc, \ucf54\ub4dc\ub97c \uc77d\uace0 \ub9ac\ubdf0\ud558\ub294 \ubd80\ubd84\uc740 \ub9e4\uc6b0 \uc5b4\ub824\uc6cc\uc9c8 \uac83\uc784\uc744 \uc18c\uac1c\ud558\ub294 \uae07\uc785\ub2c8\ub2e4. \uc88b\uc740 \uae30\uc220\uc774\uc9c0\ub9cc, \uc8fc\ub2c8\uc5b4\uac19\uc774 \uc2dc\ucf1c\uc57c \ud55c\ub2e4\ub294 \uac83\uc774\uc8e0.</p><h2 data-notion-block-id=\\"305e548d-8a8e-8005-9d8e-f1ce18d187ea\\" id=\\"305e548d-8a8e-8005-9d8e-f1ce18d187ea\\">CSS \uc120\ud0dd\uc790\uc758 \ub2e4\uc591\ud654(2026)</h2><a href=\\"https://www.projectwallace.com/the-css-selection/2026\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.projectwallace.com/the-css-selection/2026</a><p data-notion-block-id=\\"305e548d-8a8e-8033-8075-c550d861cc60\\">CSS \uc120\ud0dd\uc790\ub294 \ub2e4\uc591\ud654 \ub418\uc5c8\uc2b5\ub2c8\ub2e4. \uadf8\ub9ac\uace0 CSS\ub85c \ud560 \uc218 \uc788\ub294 \ud30c\ud2b8\ub294 \ub9e4\uc6b0 \ub2e4\uc591\ud654\ub418\uc5c8\uc2b5\ub2c8\ub2e4. \uadf8\ub807\uc9c0\ub9cc \uc0ac\uc6a9\ud558\uace0 \uc788\ub294 \uc120\ud0dd\uc790\uc640 \ubb38\ubc95\uc740 \uc81c\ud55c\ub418\uc5b4\uc788\uc2b5\ub2c8\ub2e4. \uc774 \uae00\uc740 \ud1b5\uacc4\ub97c \ud1b5\ud574 \uc5b4\ub5a4 \uae30\ub2a5\uc744 \uc0ac\uc6a9\ud558\uace0 \uc788\ub294\uc9c0, \uc5b4\ub5a4 \uacfc\uac70\uc758 \uc794\uc7ac\uac00 \ub0a8\uc544\uc788\ub294\uc9c0 \uc18c\uac1c\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4. \uc5b4\ub5a4 \uc0c8\ub85c\uc6b4 \uc720\uc6a9\ud55c \uae30\ub2a5\uc774 \uc788\ub294\uc9c0 \ubd84\uc11d\ud558\uae30\uc5d0 \uc88b\uc73c\ubbc0\ub85c, \ud55c \ubc88 \uc0b4\ud3b4\ubcf4\uc2dc\uae38 \ucd94\ucc9c\ub4dc\ub9bd\ub2c8\ub2e4.</p><h1 data-notion-block-id=\\"304e548d-8a8e-80a1-9425-fc1435818675\\">Straight to the Article: \ube5b\ub098\ub294 \uc778\uc0ac\uc774\ud2b8</h1><h2 data-notion-block-id=\\"30ae548d-8a8e-8043-bd9c-f4942b282d41\\" id=\\"30ae548d-8a8e-8043-bd9c-f4942b282d41\\">Next.js\ub97c \ud68c\uc0ac\uc5d0\uc11c \uc0ac\uc6a9\ud558\ub824\uba74</h2><a href=\\"https://techhub.iodigital.com/articles/nextjs-at-enterprise-level\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://techhub.iodigital.com/articles/nextjs-at-enterprise-level</a><p data-notion-block-id=\\"306e548d-8a8e-8036-a3fe-c4d9a87e50c5\\">Next.js \uacf5\uc2dd\ubb38\uc11c\ub294 Next.js\ub97c \ud65c\uc6a9\ud558\ub294 \ubc95\ub9cc \uc54c\ub824\uc8fc\uc9c0 \ud68c\uc0ac\uc5d0\uc11c \uc5b4\ub5bb\uac8c \uc0ac\uc6a9\ud574\uc57c \ud558\ub294\uc9c0 \uc54c\ub824\uc8fc\uc9c0\ub294 \uc54a\uc2b5\ub2c8\ub2e4. \uadf8\ub798\uc11c \uc774 \uae00\uc5d0\uc11c\ub294 \uc2a4\ucf00\uc77c\ub9c1, \uc544\ud0a4\ud14d\uccd0\ub9c1\uc744 \ube44\ub86f\ud574\uc11c \uc5ec\ub7ec\uac00\uc9c0 \ud544\uc694\ud55c \uc124\uc815\uacfc \uae30\uc220\ub4e4\uc744 \uc54c\ub824\uc90d\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"307e548d-8a8e-80c0-88e6-ebf70ac29af4\\" id=\\"307e548d-8a8e-80c0-88e6-ebf70ac29af4\\">List Virtualization, \uc2ec\ud654\ubc84\uc804</h2><a href=\\"https://rednegra.net/blog/20260212-virtual-scroll/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://rednegra.net/blog/20260212-virtual-scroll/</a><p data-notion-block-id=\\"30ae548d-8a8e-80f6-98fe-cdb8494404cc\\">\uc791\uc131\uc790\uac00 <code>&#x3C;HighTable></code>\ucef4\ud3ec\ub10c\ud2b8\ub97c \uc81c\uc791\ud558\uba74\uc11c \ud544\uc694\ud588\ub358 \uae30\uc220\uacfc \uc5b4\ub5bb\uac8c \uad6c\ud604\ud588\ub294\uc9c0 \uc0c1\ud638\uc791\uc6a9 \uac00\ub2a5\ud55c \uc608\uc2dc\uc640 \ud568\uaed8 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \uc774\uc678\uc5d0\ub3c4 <a href=\\"https://ones-to-watch.ethansup.net/news/post/2bde548d-8a8e-805b-83a0-e7a11b36e1f3#2bfe548d-8a8e-8057-becf-e03feb71cdad\\">Github \uc7ac\uad6c\uc131\ud558\uae30, RSC\uc640 CSS\ub85c</a>\ub3c4 \uc88b\uc740 \uae00\uc774\ub2c8 \uac19\uc774 \ubcf4\uc2dc\uba74 \uc88b\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"305e548d-8a8e-80e6-9ba4-d625f18e35a8\\" id=\\"305e548d-8a8e-80e6-9ba4-d625f18e35a8\\">\ub514\uc790\uc778 \uc2dc\uc2a4\ud15c \ubb38\uc11c\uc5d0\ub294 \ubb34\uc5c7\uc774 \ud544\uc694\ud560\uae4c</h2><a href=\\"https://zeroheight.com/blog/what-is-design-system-documentation/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://zeroheight.com/blog/what-is-design-system-documentation/</a><h2 data-notion-block-id=\\"307e548d-8a8e-8007-a285-f2b6e04f0d16\\" id=\\"307e548d-8a8e-8007-a285-f2b6e04f0d16\\">\ud398\uc774\uc9c0\ub97c \ub9cc\ub4e4\uae30\ubcf4\ub2e8 \ucef4\ud3ec\ub10c\ud2b8\uac00 \uc911\uc2ec\uc774 \ub420\uac83\uc774\ub2e4.</h2><a href=\\"https://bitsandbytes.dev/posts/components-will-kill-pages\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://bitsandbytes.dev/posts/components-will-kill-pages</a><p data-notion-block-id=\\"30ae548d-8a8e-8056-82e3-d83017c72e0b\\">AI\uc2dc\ub300\uc5d0 \ud398\uc774\uc9c0\ub97c \ub9cc\ub4dc\ub294 \uc0ac\ub78c\ubcf4\ub2e4 \ucef4\ud3ec\ub10c\ud2b8\uac00 \uc911\uc2ec\uc774 \ub420 \uac83\uc774\ub77c\ub294 \uac04\ub2e8\ud55c \uc5d0\uc138\uc774\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"305e548d-8a8e-80eb-ad51-e020f800b11a\\" id=\\"305e548d-8a8e-80eb-ad51-e020f800b11a\\">LLM\uc774 JS\uc758 \ud5c8\uc810\uc744 \ucc3e\uc558\ub2e4.</h2><a href=\\"https://winfunc.com/blog/recent-0-days-in-nodejs-and-react-were-found-by-an-ai\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://winfunc.com/blog/recent-0-days-in-nodejs-and-react-were-found-by-an-ai</a><p data-notion-block-id=\\"30be548d-8a8e-8060-a97c-e07535321fb7\\">LLM\uc744 \uc774\uc6a9\ud558\uc5ec \ub77c\uc774\ube0c\ub7ec\ub9ac\ub098 \ub7f0\ud0c0\uc784\uc758 \ucde8\uc57d\uc810\uc744 \ucc3e\uc544\ub0c8\ub2e4\uba74, LLM\uc758 \ud658\uac01\uc73c\ub85c \uc778\ud55c \uc624\ud0d0\uc9c0\uc77c \uc218 \uc788\uc2b5\ub2c8\ub2e4. \uc774 \uae00\uc5d0\uc11c\ub294 LLM\uc744 \uae30\ubc18\uc73c\ub85c \ud658\uac01\uc5d0\uc11c \ubc97\uc5b4\ub098\uc11c \ucde8\uc57d\uc810 \ud0d0\uc9c0 \uc544\ud0a4\ud14d\uccd0\ub97c \uc5b4\ub5bb\uac8c \uad6c\uc131\ud588\ub294\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"305e548d-8a8e-80b7-bca9-db0a0c6e864c\\" id=\\"305e548d-8a8e-80b7-bca9-db0a0c6e864c\\"><code>Symbol.dispose()</code>\ub294 \uc5b4\ub514\uc5d0 \uc0ac\uc6a9\ub418\ub294\uac00</h2><a href=\\"https://piccalil.li/blog/its-about-to-get-a-lot-easier-for-your-javascript-to-clean-up-after-itself/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://piccalil.li/blog/its-about-to-get-a-lot-easier-for-your-javascript-to-clean-up-after-itself/</a><h2 data-notion-block-id=\\"30ae548d-8a8e-80a7-9f80-f1e33a1c44c6\\" id=\\"30ae548d-8a8e-80a7-9f80-f1e33a1c44c6\\">\uc778\uc1c4\uc9c8\uac10\uc744 GLSL\ub85c \ud45c\ud604\ud558\uae30</h2><a href=\\"https://blog.maximeheckel.com/posts/shades-of-halftone/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.maximeheckel.com/posts/shades-of-halftone/</a><h2 data-notion-block-id=\\"307e548d-8a8e-80fa-92be-d9674f52943b\\" id=\\"307e548d-8a8e-80fa-92be-d9674f52943b\\">State of React 2025 \uc5d0\ub514\uc158</h2><a href=\\"https://2025.stateofreact.com/ko-KR/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://2025.stateofreact.com/ko-KR/</a><p data-notion-block-id=\\"305e548d-8a8e-80cb-8332-e58225e737d6\\">\uc774\uc804\uc758 <a href=\\"https://ones-to-watch.ethansup.net/news/post/301e548d-8a8e-8053-a33f-e9bcc696088d#301e548d-8a8e-80c4-921d-d6b95f2fee48\\">State of JS</a>\uc640 \uc704\uc758 CSS \uc120\ud0dd\uae30 \ubd84\uc11d\uae00\uacfc \uac19\uc774 \ud1b5\uacc4\uc640 \uac19\uc774 \uc88b\uc740 \ubd84\uc11d\uc744 \uc81c\uacf5\ud574\uc8fc\ubbc0\ub85c, \ud55c \ubc88 \uc0b4\ud3b4\ubcf4\uc2dc\uae38 \ucd94\ucc9c\ub4dc\ub9bd\ub2c8\ub2e4.</p><h1 data-notion-block-id=\\"304e548d-8a8e-8001-b7c0-e80f3628a5f5\\">Fresh Finds: \ub193\uce58\uc9c0 \ub9d0\uc544\uc57c \ud560 \uc18c\uc2dd</h1><a href=\\"https://eslint.org/blog/2026/02/eslint-v10.0.0-released/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://eslint.org/blog/2026/02/eslint-v10.0.0-released/</a><p data-notion-block-id=\\"307e548d-8a8e-80a3-9831-f7e12cea3b1a\\">ESLint 10\ubc84\uc804\uc774 \ucd9c\uc2dc\ub418\uc5c8\uc2b5\ub2c8\ub2e4. Legacy Config\uac00 \uc0ac\ub77c\uc84c\uace0, \uacfc\uac70\uc758 \ub178\ub4dc \ubc84\uc804\uc774 \ub354 \uc774\uc0c1 \uc9c0\uc6d0\ub418\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. <a href=\\"https://nodejs.org/ko/download\\">fnm\uc774 \ub514\ud3f4\ud2b8 nodejs \uc124\uce58\uc5d0 \uad8c\uc7a5\ub418\uace0 \uc788</a>\uc73c\ubbc0\ub85c, node \ubc84\uc804\uc744 \uccb4\ud06c\ud558\ub294 \uac83\ub3c4 \ud544\uc694\ud574\ubcf4\uc785\ub2c8\ub2e4.</p><a href=\\"https://reactnative.dev/blog/2026/02/11/react-native-0.84\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://reactnative.dev/blog/2026/02/11/react-native-0.84</a><p data-notion-block-id=\\"304e548d-8a8e-80f9-aa3e-f9d4efd85d8b\\">React Native\uac00 \uc0c8\ub85c\uc6b4 \ub9c8\uc774\ub108 \ubc84\uc804\uc774 \ub098\uc624\uba74\uc11c JS \ub7f0\ud0c0\uc784\uc744 Hermes\ub97c \uae30\ubcf8\uc73c\ub85c \uc81c\uacf5\ud569\ub2c8\ub2e4.</p><a href=\\"https://webpack.js.org/blog/2026-04-02-roadmap-2026/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://webpack.js.org/blog/2026-04-02-roadmap-2026/</a><p data-notion-block-id=\\"304e548d-8a8e-8007-90cf-f91b5208ce52\\">webpack\uc758 2026\ub144 \ub85c\ub4dc\ub9f5\uc744 \ubcf4\uc5ec\uc8fc\ub294 \uae00\uc785\ub2c8\ub2e4.</p><a href=\\"https://github.com/mutativejs/travels\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://github.com/mutativejs/travels</a><p data-notion-block-id=\\"306e548d-8a8e-80f2-b460-d6922a770d76\\">\ud504\ub808\uc784\uc6cc\ud06c \uc81c\uc57d \uc5c6\uc774 undo/redo\uae30\ub2a5\uc744 \uc81c\uacf5\ud558\ub294 \ub77c\uc774\ube0c\ub7ec\ub9ac\uc785\ub2c8\ub2e4.</p><a href=\\"https://devblogs.microsoft.com/typescript/announcing-typescript-6-0-beta/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://devblogs.microsoft.com/typescript/announcing-typescript-6-0-beta/</a><p data-notion-block-id=\\"306e548d-8a8e-8067-baf6-ed8ab0f20253\\">TypeScript 6\ubc84\uc804 \ubca0\ud0c0\uac00 \ub098\uc624\uba74\uc11c, 7\ubc84\uc804\uc744 \ub300\ube44\ud55c \uae30\ub2a5 \ucd94\uac00/\uc81c\uac70\ub97c \uc9c4\ud589\ud558\uace0 \uc788\uc2b5\ub2c8\ub2e4. tsgo\ub97c \uc81c\ub300\ub85c \uc801\uc6a9\ud560 \uc218 \uc788\ub3c4\ub85d \uc8fc\ubaa9\ud574\uc57c\uaca0\uc2b5\ub2c8\ub2e4.</p><a href=\\"https://blog.platformatic.dev/debugging-nodejs-performance-with-ai\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.platformatic.dev/debugging-nodejs-performance-with-ai</a><p data-notion-block-id=\\"307e548d-8a8e-8054-8513-c9a7ca420e6c\\">Node.js\uc758 \ubcf5\uc7a1\ud55c \ub514\ubc84\uae45\uc744 Agent\uac00 \uc774\ud574\ud560 \uc218 \uc788\ub3c4\ub85d \ub514\ubc84\uac70 \ubd84\uc11d\uc744 \ub9c8\ud06c\ub2e4\uc6b4\uc73c\ub85c \uc81c\uacf5\ud558\ub294 \ub77c\uc774\ube0c\ub7ec\ub9ac\uc785\ub2c8\ub2e4.</p><a href=\\"https://blog.cloudflare.com/markdown-for-agents/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.cloudflare.com/markdown-for-agents/</a><p data-notion-block-id=\\"307e548d-8a8e-8060-97c1-e51193503fa4\\">Agent\ub97c \uc704\ud55c \ubb38\uc11c\ub97c \uc81c\uacf5\ud558\uae30 \uc704\ud55c \uc0c8\ub85c\uc6b4 \ud45c\uc900\uc744 \uc81c\uc2dc\ud558\ub294 Cloudflare\uc785\ub2c8\ub2e4.</p>"}')}}]);